    --leo: #3b82f6;
    --meo: #8b5cf6;
    --geo: #f59e0b;
    --heo: #ef4444;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }}
  .report {{ max-width: 1200px; margin: 0 auto; padding: 40px 32px; }}
  header {{
    text-align: center;
    margin-bottom: 48px;
    padding-bottom: 32px;
    border-bottom: 1px solid var(--border);
  }}
  header h1 {{
    font-size: 2rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    margin-bottom: 8px;
    background: linear-gradient(135deg, #e2e8f0, #3b82f6);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }}
  header .subtitle {{
    color: var(--text-muted);
    font-size: 1rem;
  }}
  header .epoch {{
    color: var(--text-muted);
    font-size: 0.85rem;
    margin-top: 8px;
  }}

  /* KPI Block */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 48px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 16px;
    text-align: center;
  }}
  .kpi-card .kpi-value {{
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--accent);
    line-height: 1.2;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.8rem;
    color: var(--text-muted);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }}

  /* Sections */
  section {{
    margin-bottom: 56px;
  }}
  section h2 {{
    font-size: 1.4rem;
    font-weight: 600;
    margin-bottom: 8px;
    color: #fff;
  }}
  section h2 .section-num {{
    color: var(--accent);
    margin-right: 8px;
  }}
  section .section-desc {{
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 24px;
  }}

  /* Two-column layout */
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    align-items: start;
  }}
  .three-col {{
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
  }}

  /* Chart containers */
  .chart-container {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    position: relative;
  }}
  .chart-container canvas {{
    max-height: 380px;
  }}
  .chart-container h3 {{
    font-size: 0.95rem;
    font-weight: 500;
    margin-bottom: 16px;
    color: var(--text-muted);
  }}

  /* Full-width chart */
  .chart-full {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px;
    margin-top: 24px;
  }}
  .chart-full canvas {{
    max-height: 420px;
  }}

  /* Tables */
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
  }}
  th {{
    text-align: left;
    padding: 10px 12px;
    border-bottom: 2px solid var(--border);
    color: var(--text-muted);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-weight: 500;
  }}
  td {{
    padding: 9px 12px;
    border-bottom: 1px solid var(--border);
  }}
  td.num {{
    text-align: right;
    font-variant-numeric: tabular-nums;
  }}
  .other-row td {{
    color: var(--text-muted);
    font-style: italic;
  }}

  /* Highlight callout */
  .callout {{
    background: linear-gradient(135deg, rgba(59,130,246,0.1), rgba(6,182,212,0.08));
    border: 1px solid rgba(59,130,246,0.3);
    border-radius: 12px;
    padding: 20px 24px;
    margin: 20px 0;
  }}
  .callout p {{
    margin: 4px 0;
  }}
  .callout .highlight {{
    color: var(--accent2);
    font-weight: 600;
  }}

  /* Stat inline */
  .stat {{ color: var(--accent); font-weight: 600; }}

  /* Footer */
  footer {{
    text-align: center;
    padding: 32px 0;
    border-top: 1px solid var(--border);
    color: var(--text-muted);
    font-size: 0.8rem;
    margin-top: 40px;
  }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .two-col, .three-col {{ grid-template-columns: 1fr; }}
  }}
  @media (max-width: 600px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .report {{ padding: 20px 16px; }}
  }}
</style>
</head>
<body>
<div class="report">

<header>
  <h1>Active Satellites in Earth Orbit</h1>
  <p class="subtitle">2026 Catalog Analysis — Data-Driven Orbital Environment Assessment</p>
  <p class="epoch">Data epoch: {epoch_min} to {epoch_max} | Source: CelesTrak / NORAD TLE</p>
</header>

<!-- ─── KPI Block ────────────────────────────────────────────────────── -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-value">{total_sats:,}</div>
    <div class="kpi-label">Total Active Satellites</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{leo_share}%</div>
    <div class="kpi-label">LEO Share</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{starlink_count:,}</div>
    <div class="kpi-label">Starlink Satellites</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{median_incl}°</div>
    <div class="kpi-label">Median Inclination</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{since_2020_count:,}</div>
    <div class="kpi-label">Launched Since 2020</div>
  </div>
</div>

<!-- ─── Section 1: Catalog Overview ──────────────────────────────────── -->
<section id="overview">
  <h2><span class="section-num">01</span>Catalog Overview & Key Figures</h2>
  <p class="section-desc">
    This catalog captures <span class="stat">{total_sats:,}</span> active satellites tracked by NORAD and published via CelesTrak.
    Orbital elements are current as of the epoch range {epoch_min} through {epoch_max}.
    Starlink alone accounts for <span class="stat">{starlink_count:,}</span> satellites ({starlink_share}% of the total),
    fundamentally reshaping the statistical profile of the orbital environment.
    Of all active satellites, <span class="stat">{since_2020_count:,}</span> ({since_2020_share}%) were launched in 2020 or later.
  </p>
  <div class="callout">
    <p><strong>Key Finding:</strong> The median inclination of <span class="highlight">{median_incl}°</span> reflects the dominance of
    near-polar sun-synchronous and mid-inclination LEO shells, heavily influenced by Starlink's ~53° and ~97° orbital planes.</p>
  </div>
</section>

<!-- ─── Section 2: Orbital Regime Classification ─────────────────────── -->
<section id="orbit-regime">
  <h2><span class="section-num">02</span>Orbital Regime Classification</h2>
  <p class="section-desc">
    Satellites are classified using MEAN_MOTION thresholds:
    <strong>LEO</strong> (&gt;14 rev/day), <strong>MEO</strong> (2–14 rev/day),
    <strong>GEO</strong> (0.9–&lt;2 rev/day), and <strong>HEO</strong> (eccentricity &gt;0.1 with MM &lt;14).
  </p>
  <div class="two-col">
    <div class="chart-container">
      <h3>Distribution by Orbital Regime</h3>
      <canvas id="regimeChart"></canvas>
    </div>
    <div>
      <table>
        <thead>
          <tr><th>Regime</th><th>Count</th><th>Share</th></tr>
        </thead>
        <tbody>
          {regime_table_rows}
        </tbody>
      </table>
      <div class="callout" style="margin-top:16px;">
        <p><strong>Starlink effect on LEO:</strong> {leo_starlink_share_of_leo}% of all LEO satellites are Starlink.
        Excluding Starlink, LEO contains <span class="highlight">{leo_non_starlink_count:,}</span> satellites —
        meaning Starlink nearly doubles the LEO population on its own.</p>
      </div>
    </div>
  </div>
</section>

<!-- ─── Section 3: Constellation Breakdown ───────────────────────────── -->
<section id="constellation-analysis">
  <h2><span class="section-num">03</span>Major Constellation & Operator Breakdown</h2>
  <p class="section-desc">
    Constellation membership is derived from OBJECT_NAME prefixes. The top 15 named constellations
    account for <span class="stat">{constellation_counts.sum():,}</span> satellites
    ({round(constellation_counts.sum()/total_sats*100,1)}% of the catalog).
  </p>
  <div class="two-col">
    <div class="chart-container" style="grid-column: span 1;">
      <h3>Top 15 Constellations by Satellite Count</h3>
      <canvas id="constellationChart"></canvas>
    </div>
    <div>
      <table>
        <thead>
          <tr><th>Constellation</th><th>Count</th><th>Share</th></tr>
        </thead>
        <tbody>
          {constellation_table_rows}
        </tbody>
      </table>
    </div>
  </div>
  <div class="callout">
    <p><strong>Concentration risk:</strong> A single operator (SpaceX/Starlink) controls <span class="highlight">{starlink_share}%</span>
    of all active satellites. The top two constellations (Starlink + OneWeb) together account for
    <span class="highlight">{round((starlink_count + constellation_counts.get('OneWeb', 0))/total_sats*100,1)}%</span>
    of the catalog, raising questions about single-operator dependency and spectrum concentration.</p>
  </div>
</section>

<!-- ─── Section 4: Launch Year Trends ────────────────────────────────── -->
<section id="launch-trends">
  <h2><span class="section-num">04</span>Launch Year Trends</h2>
  <p class="section-desc">
    Launch year is extracted from the first four characters of OBJECT_ID. The chart below shows
    the number of currently active satellites by launch year, along with the cumulative fleet size.
    The post-2019 acceleration driven by mega-constellations is the defining trend.
  </p>
  <div class="chart-full">
    <h3>Active Satellites by Launch Year (Bar) & Cumulative Fleet Size (Line)</h3>
    <canvas id="launchTrendChart"></canvas>
  </div>
  <div style="margin-top:24px;" class="two-col">
    <div class="chart-container">
      <h3>Post-2020 Launch Volume by Year</h3>
      <canvas id="recentLaunchChart"></canvas>
    </div>
    <div>
      <table>
        <thead>
          <tr><th>Year</th><th>Active Sats Launched</th></tr>
        </thead>
        <tbody>
          {recent_table_rows}
        </tbody>
      </table>
      <div class="callout" style="margin-top:16px;">
        <p><strong>Acceleration:</strong> <span class="highlight">{since_2020_share}%</span> of all active satellites
        were launched since 2020. The period 2020–2026 accounts for <span class="highlight">{since_2020_count:,}</span> satellites,
        compared to just {total_sats - since_2020_count:,} launched in all prior decades combined.</p>
      </div>
    </div>
  </div>
</section>

<!-- ─── Section 5: Orbital Parameters ────────────────────────────────── -->
<section id="orbital-characteristics">
  <h2><span class="section-num">05</span>Orbital Parameter Deep Dive</h2>
  <p class="section-desc">
    Distribution analysis of the three key orbital elements: inclination, eccentricity, and mean motion.
    These parameters define the physical shells occupied by the active fleet.
  </p>
  <div class="three-col">
    <div class="chart-container">
      <h3>Inclination Distribution</h3>
      <canvas id="inclChart"></canvas>
    </div>
    <div class="chart-container">
      <h3>Eccentricity Distribution</h3>
      <canvas id="eccChart"></canvas>
    </div>
    <div class="chart-container">
      <h3>Mean Motion Distribution</h3>
      <canvas id="mmChart"></canvas>
    </div>
  </div>
  <div style="margin-top:24px;" class="two-col">
    <div>
      <h3 style="font-size:0.95rem;margin-bottom:12px;color:var(--text-muted);">Inclination Statistics by Regime</h3>
      <table>
        <thead>
          <tr><th>Regime</th><th>Median</th><th>Mean</th><th>Min</th><th>Max</th></tr>
        </thead>
        <tbody>
          {incl_regime_rows}
        </tbody>
      </table>
    </div>
    <div>
      <h3 style="font-size:0.95rem;margin-bottom:12px;color:var(--text-muted);">Notable Orbital Outliers</h3>
      <table>
        <thead>
          <tr><th>Satellite</th><th>Eccentricity</th><th>Incl.</th><th>Mean Motion</th></tr>
        </thead>
        <tbody>
          {high_ecc_rows}
        </tbody>
      </table>
    </div>
  </div>
  <div class="callout">
    <p><strong>Eccentricity:</strong> The overwhelming majority of satellites (<span class="highlight">{round(len(df[df['ECCENTRICITY']<0.01])/total_sats*100,1)}%</span>)
    have near-circular orbits (eccentricity &lt;0.01). Highly eccentric orbits (ecc &gt;0.1) are dominated by
    Molniya-type and scientific missions — only <span class="highlight">{len(df[df['ECCENTRICITY']>0.1])}</span> satellites qualify as HEO.</p>
    <p style="margin-top:8px;"><strong>Inclination:</strong> The two dominant inclination bands are ~53° (Starlink shell) and
    ~97° (sun-synchronous orbit), clearly visible in the distribution. Starlink's median inclination is <span class="highlight">{starlink_incl_median}°</span>.</p>
  </div>
</section>

<!-- ─── Section 6: Conclusions ───────────────────────────────────────── -->
<section id="conclusions">
  <h2><span class="section-num">06</span>Key Takeaways & Outlook</h2>
  <p class="section-desc">
    Synthesis of findings for space-sustainability policy and constellation licensing decisions.
  </p>
  <div class="callout">
    <p><strong>1. Mega-constellation dominance:</strong> Starlink's <span class="highlight">{starlink_count:,}</span> satellites
    represent {starlink_share}% of all active spacecraft. Any statistical analysis of the orbital environment must
    segment Starlink from the rest of the fleet to avoid distorted conclusions.</p>
    <p style="margin-top:10px;"><strong>2. LEO congestion is accelerating:</strong> LEO holds <span class="highlight">{leo_count:,}</span> satellites
    ({leo_share}% of total), with <span class="highlight">{leo_starlink_share_of_leo}%</span> of those belonging to Starlink.
    The post-2020 surge is almost entirely a LEO phenomenon driven by commercial broadband constellations.</p>
    <p style="margin-top:10px;"><strong>3. Rapid fleet turnover:</strong> <span class="highlight">{since_2020_share}%</span> of the active
    fleet was launched since 2020. This implies a young population with short design lifetimes, increasing
    replacement launch rates and end-of-life disposal demands.</p>
    <p style="margin-top:10px;"><strong>4. Orbital regime balance is shifting:</strong> GEO — long the primary orbit for
    communications — now holds only <span class="highlight">{regime_data.get('GEO', {}).get('pct', 0)}%</span> of active satellites.
    Policy and spectrum frameworks designed for a GEO-centric era may need updating for the LEO-dominated reality.</p>
    <p style="margin-top:10px;"><strong>5. Concentration risk:</strong> A single operator controlling over {starlink_share}% of
    all active satellites creates systemic dependencies for space situational awareness, collision avoidance,
    and debris mitigation. Regulatory frameworks should consider operator-level concentration limits.</p>
  </div>
</section>

<footer>
  <p>Active Satellites in Earth Orbit — 2026 Catalog Analysis | Data: CelesTrak / NORAD TLE | Generated from catalog of {total_sats:,} objects</p>
</footer>

</div>

<script>
// ─── Color palettes ──────────────────────────────────────────────────────
const regimeColors = {{
  LEO: '#3b82f6',
  MEO: '#8b5cf6',
  GEO: '#f59e0b',
  HEO: '#ef4444',
  Other: '#6b7280',
  Unknown: '#374151'
}};

Chart.defaults.color = '#8899b0';
Chart.defaults.borderColor = '#2a3a54';
Chart.defaults.font.family = "'Inter', sans-serif";

// ─── Regime Doughnut ─────────────────────────────────────────────────────
const regimeData = {regime_chart_data};
new Chart(document.getElementById('regimeChart'), {{
  type: 'doughnut',
  data: {{
    labels: regimeData.labels,
    datasets: [{{
      data: regimeData.values,
      backgroundColor: regimeData.labels.map(l => regimeColors[l] || '#6b7280'),
      borderWidth: 0,
      hoverOffset: 8
    }}]
  }},
  options: {{
    responsive: true,
    cutout: '60%',
    plugins: {{
      legend: {{ position: 'bottom', labels: {{ padding: 16, usePointStyle: true, pointStyle: 'circle' }} }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.label}}: ${{ctx.raw.toLocaleString()}} (${{regimeData.pcts[ctx.dataIndex]}}%)`
        }}
      }}
    }}
  }}
}});

// ─── Constellation Horizontal Bar ───────────────────────────────────────
const constData = {constellation_chart_data};
const constColors = constData.labels.map((l, i) => {{
  if (l === 'Starlink') return '#3b82f6';
  if (l === 'OneWeb') return '#06b6d4';
  return `hsl(${{210 + i * 18}}, 60%, 55%)`;
}});
new Chart(document.getElementById('constellationChart'), {{
  type: 'bar',
  data: {{
    labels: constData.labels,
    datasets: [{{
      data: constData.values,
      backgroundColor: constColors,
      borderRadius: 4,
      barThickness: 18
    }}]
  }},
  options: {{
    indexAxis: 'y',
    responsive: true,
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.raw.toLocaleString()}} sats (${{constData.pcts[ctx.dataIndex]}}%)`
        }}
      }}
    }},
    scales: {{
      x: {{ grid: {{ color: '#1c2a42' }}, ticks: {{ callback: v => v.toLocaleString() }} }},
      y: {{ grid: {{ display: false }} }}
    }}
  }}
}});

// ─── Launch Year Trend (combo bar + line) ───────────────────────────────
const launchData = {launch_trend_data};
new Chart(document.getElementById('launchTrendChart'), {{
  type: 'bar',
  data: {{
    labels: launchData.years,
    datasets: [
      {{
        label: 'Annual Active Sats',
        data: launchData.counts,
        backgroundColor: launchData.years.map(y => y >= 2020 ? 'rgba(59,130,246,0.8)' : 'rgba(59,130,246,0.35)'),
        borderRadius: 2,
        order: 2
      }},
      {{
        label: 'Cumulative Fleet',
        data: launchData.cumulative,
        type: 'line',
        borderColor: '#06b6d4',
        borderWidth: 2.5,
        pointRadius: 0,
        pointHoverRadius: 4,
        fill: false,
        tension: 0.3,
        yAxisID: 'y1',
        order: 1
      }}
    ]
  }},
  options: {{
    responsive: true,
    interaction: {{ mode: 'index', intersect: false }},
    plugins: {{
      legend: {{ position: 'top', labels: {{ usePointStyle: true, pointStyle: 'circle', padding: 20 }} }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.dataset.label}}: ${{ctx.raw.toLocaleString()}}`
        }}
      }}
    }},
    scales: {{
      x: {{ grid: {{ display: false }}, ticks: {{ maxRotation: 45, autoSkip: true, maxTicksLimit: 25 }} }},
      y: {{
        position: 'left',
        grid: {{ color: '#1c2a42' }},
        ticks: {{ callback: v => v.toLocaleString() }},
        title: {{ display: true, text: 'Annual Count', color: '#8899b0' }}
      }},
      y1: {{
        position: 'right',
        grid: {{ drawOnChartArea: false }},
        ticks: {{ callback: v => v.toLocaleString() }},
        title: {{ display: true, text: 'Cumulative Fleet', color: '#8899b0' }}
      }}
    }}
  }}
}});

// ─── Recent Launch Bar ──────────────────────────────────────────────────
const recentData = {recent_launch_data};
new Chart(document.getElementById('recentLaunchChart'), {{
  type: 'bar',
  data: {{
    labels: recentData.years,
    datasets: [{{
      data: recentData.counts,
      backgroundColor: ['#3b82f6','#3b82f6','#3b82f6','#3b82f6','#3b82f6','#3b82f6','#3b82f6'],
      borderRadius: 6,
      barThickness: 36
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.raw.toLocaleString()}} satellites`
        }}
      }}
    }},
    scales: {{
      x: {{ grid: {{ display: false }} }},
      y: {{ grid: {{ color: '#1c2a42' }}, ticks: {{ callback: v => v.toLocaleString() }} }}
    }}
  }}
}});

// ─── Inclination Histogram ──────────────────────────────────────────────
const inclData = {incl_chart_data};
new Chart(document.getElementById('inclChart'), {{
  type: 'bar',
  data: {{
    labels: inclData.labels,
    datasets: [{{
      data: inclData.values,
      backgroundColor: 'rgba(139,92,246,0.7)',
      borderRadius: 3
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ legend: {{ display: false }} }},
    scales: {{
      x: {{ grid: {{ display: false }}, ticks: {{ maxRotation: 45, font: {{ size: 9 }} }} }},
      y: {{ grid: {{ color: '#1c2a42' }}, ticks: {{ callback: v => v >= 1000 ? (v/1000)+'k' : v }} }}
    }}
  }}
}});

// ─── Eccentricity Histogram ─────────────────────────────────────────────
const eccData = {ecc_chart_data};
new Chart(document.getElementById('eccChart'), {{
  type: 'bar',
  data: {{
    labels: eccData.labels,
    datasets: [{{
      data: eccData.values,
      backgroundColor: 'rgba(245,158,11,0.7)',
      borderRadius: 3
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ legend: {{ display: false }} }},
    scales: {{
      x: {{ grid: {{ display: false }}, ticks: {{ maxRotation: 45, font: {{ size: 9 }} }} }},
      y: {{ grid: {{ color: '#1c2a42' }}, ticks: {{ callback: v => v >= 1000 ? (v/1000)+'k' : v }} }}
    }}
  }}
}});

// ─── Mean Motion Histogram ──────────────────────────────────────────────
const mmData = {mm_chart_data};
new Chart(document.getElementById('mmChart'), {{
  type: 'bar',
  data: {{
    labels: mmData.labels,
    datasets: [{{
      data: mmData.values,
      backgroundColor: 'rgba(6,182,212,0.7)',
      borderRadius: 3
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ legend: {{ display: false }} }},
    scales: {{
      x: {{ grid: {{ display: false }}, ticks: {{ maxRotation: 45, font: {{ size: 9 }} }} }},
      y: {{ grid: {{ color: '#1c2a42' }}, ticks: {{ callback: v => v >= 1000 ? (v/1000)+'k' : v }} }}
    }}
  }}
}});
</script>

</body>
</html>
"""

with open('/app/output/final_report.html', 'w') as f:
    f.write(html)

print("Report generated successfully at /app/output/final_report.html")
print(f"Total satellites: {total_sats:,}")
print(f"LEO share: {leo_share}%")
print(f"Starlink: {starlink_count:,} ({starlink_share}%)")
print(f"Median inclination: {median_incl}°")
print(f"Launched since 2020: {since_2020_count:,} ({since_2020_share}%)")
print(f"\nRegime breakdown:")
