# ─── Orbital Regime Classification ──────────────────────────────────────────
# LEO: MEAN_MOTION > 14
# MEO: 2 <= MEAN_MOTION <= 14
# GEO: 0.9 <= MEAN_MOTION < 2
# HEO: ECCENTRICITY > 0.1 (highly eccentric, regardless of mean motion)

def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if pd.isna(mm):
        return 'Unknown'
    if ecc > 0.1 and mm < 14:
        return 'HEO'
    if mm > 14:
        return 'LEO'
    if mm >= 2:
        return 'MEO'
    if mm >= 0.9:
        return 'GEO'
    return 'Other'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)
regime_counts = df['ORBIT_REGIME'].value_counts().to_dict()
regime_order = ['LEO', 'MEO', 'GEO', 'HEO', 'Other', 'Unknown']
regime_data = {}
for r in regime_order:
    if r in regime_counts:
